using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using UnityEngine.InputSystem;using Newtonsoft.Json;
public static class B2Review {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B2_Cooling/";static Vector3 origin=new Vector3(19,-34,-1);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");Directory.CreateDirectory(O);return s;}
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=76){var go=new GameObject("B2Review_Temporary");go.hideFlags=HideFlags.HideAndDontSave;var c=go.AddComponent<Camera>();c.transform.position=origin+pos;c.transform.LookAt(origin+target);c.useOcclusionCulling=false;c.nearClipPlane=.04f;c.farClipPlane=100;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Capture(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=player.activeSelf;player.SetActive(false);try{Shot("01_entry",new Vector3(0,1.65f,-8),new Vector3(0,3.5f,3));Shot("02_upper",new Vector3(-5.7f,5.25f,4.6f),new Vector3(3,1.2f,-2));Shot("03_pumps",new Vector3(-.3f,1.6f,-4.2f),new Vector3(-2.7f,1.1f,-.5f),67);Shot("04_maintenance",new Vector3(-6.3f,1.65f,2.3f),new Vector3(-8.65f,1.1f,2.65f),65);Shot("05_stair",new Vector3(-4.3f,1.65f,-7.8f),new Vector3(-6.2f,2.2f,-3.4f),76);Shot("06_control",new Vector3(2.7f,1.65f,5.7f),new Vector3(3.05f,1.20f,7.55f),60);}finally{player.SetActive(on);EditorSceneManager.OpenScene(s.path);}return new{images=6};}
 public static Dictionary<string,Vector3[]> Routes(){var r=new Dictionary<string,Vector3[]>();
 r["central_floor"]=new[]{new Vector3(0,0,-7.8f),new Vector3(0,0,5.2f)};
 foreach(int sign in new[]{-1,1}){float x=sign*6.2f;r[(sign<0?"west":"east")+"_stairs_up"]=new[]{new Vector3(x,0,-8.0f),new Vector3(x,0,-7.6f),new Vector3(x,3.6f,-1.8f),new Vector3(x,3.6f,2.2f)};r[(sign<0?"west":"east")+"_stairs_down"]=new[]{new Vector3(x,3.6f,2.2f),new Vector3(x,3.6f,-1.8f),new Vector3(x,0,-8.0f)};r[(sign<0?"west":"east")+"_base_access"]=new[]{new Vector3(0,0,-7.8f),new Vector3(x,0,-7.8f)};r[(sign<0?"west":"east")+"_inner_bypass"]=new[]{new Vector3(0,0,-6f),new Vector3(sign*1.2f,0,-5),new Vector3(sign*1.2f,0,5.2f)};}
 r["upper_crossing"]=new[]{new Vector3(-6.2f,3.6f,2.0f),new Vector3(-5.8f,3.6f,2.1f),new Vector3(-5.8f,3.6f,4.5f),new Vector3(5.8f,3.6f,4.5f),new Vector3(5.8f,3.6f,2.1f),new Vector3(6.2f,3.6f,2.0f)};
 r["maintenance_bench"]=new[]{new Vector3(0,0,-6f),new Vector3(-4.7f,0,-6),new Vector3(-4.9f,0,-2.8f),new Vector3(-7.8f,0,-2.8f),new Vector3(-7.5f,0,2.7f)};
 r["rear_service"]=new[]{new Vector3(0,0,3f),new Vector3(0,0,5.3f),new Vector3(3.05f,0,5.3f),new Vector3(3.05f,0,6.6f)};
 return r;}
 public static object Walk(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var saved=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();try{foreach(var route in Routes()){var points=route.Value.Select(v=>v+origin).ToArray();cc.enabled=false;player.transform.position=points[0]+Vector3.up*(cc.height*.5f-cc.center.y+.035f);cc.enabled=true;Physics.SyncTransforms();int steps=0,index=0;bool passed=true;float remaining=0;Vector3 target=points[0];foreach(var to in points.Skip(1)){index++;target=to;int limit=(int)(Vector3.Distance(player.transform.position,to)/.05f)+120;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.025f)break;cc.Move(d.normalized*Mathf.Min(.05f,remaining)+Vector3.down*.045f);steps++;}if(remaining>.08f){passed=false;break;}}for(int i=0;i<12;i++)cc.Move(Vector3.down*.035f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float error=bottom-target.y;if(Mathf.Abs(error)>.30f)passed=false;var hit=Physics.OverlapSphere(player.transform.position+cc.center,.7f,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=cc).Select(c=>c.name).Distinct().ToArray();results.Add(new{id=route.Key,passed,steps,index,remaining,heightError=error,foot=new[]{player.transform.position.x,bottom,player.transform.position.z},nearby=hit});}}finally{cc.enabled=false;player.transform.position=saved;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"walk.json",JsonConvert.SerializeObject(results,Formatting.Indented));return results;}
 public static object Audit(){var s=Check();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var mf=all.SelectMany(t=>t.GetComponents<MeshFilter>()).ToArray();var rs=all.SelectMany(t=>t.GetComponents<Renderer>()).ToArray();var meshes=mf.Where(m=>m.sharedMesh).Select(m=>m.sharedMesh).Distinct().ToArray();var bad=new List<object>();long tri=0;foreach(var m in meshes){for(int i=0;i<m.subMeshCount;i++)tri+=(long)m.GetIndexCount(i)/3;if(!m.isReadable)continue;var v=m.vertices;var ix=m.triangles;int n=0;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)n++;if(n>0)bad.Add(new{m.name,degenerate=n});}
 var result=new{scene=s.path,saved=!s.isDirty,objects=all.Length,renderers=rs.Length,uniqueTriangles=tri,missingMeshes=mf.Count(f=>!f.sharedMesh),missingMaterials=rs.Sum(r=>r.sharedMaterials.Count(m=>!m)),missingScripts=all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),nonASCII=all.Count(t=>t.name.Any(c=>c>127)),colliders=all.Sum(t=>t.GetComponents<Collider>().Length),lights=all.Sum(t=>t.GetComponents<Light>().Length),lodGroups=all.Sum(t=>t.GetComponents<LODGroup>().Length),probes=all.Sum(t=>t.GetComponents<ReflectionProbe>().Length),meshIssues=bad,mouse=Mouse.current?.enabled,keyboard=Keyboard.current?.enabled};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
